// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        Reverter reverter = new Reverter();
        address target = address(reverter);
        uint value = 1 ether;

        vm.deal(address(this), value);
        vm.prank(address(this));
        vm.deal(address(c), value);

        uint countBefore = c.depositsCount();

        bool ok;
        try c.sendMoney(target, value) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false, "sendMoney should revert on failed call");
        assertTrue(c.depositsCount() == countBefore, "depositsCount unchanged if revert");
    }
}

contract Reverter {
    fallback() external payable {
        revert("fail");
    }
}
